"""The memory key is derived from the verified principal, not from the request.

A checkpointer takes an opaque key, so the only thing standing between two
tenants is how that key was built. Building it here means no route can accept
one from the outside.
"""

import hmac


class ThreadOwnershipError(PermissionError):
    pass


def scoped_thread_id(principal, conversation_id: str) -> str:
    """Bind the thread key to the authenticated subject."""
    return "%s:%s" % (principal.subject, conversation_id)


def assert_thread_owner(principal, thread_id: str) -> None:
    """Refuse a read whose key was not derived from this subject."""
    expected_prefix = "%s:" % principal.subject
    if not hmac.compare_digest(thread_id[:len(expected_prefix)], expected_prefix):
        raise ThreadOwnershipError("thread %r is not owned by this subject" % thread_id)

good.app/auth.py:
"""Minimal principal extraction, so the memory key has something to bind to."""

from dataclasses import dataclass

from fastapi import Header


@dataclass(frozen=True)
class Principal:
    subject: str


def get_principal(authorization: str = Header(...)) -> Principal:
    subject = verify_token(authorization.removeprefix("Bearer "))
    return Principal(subject=subject)


def verify_token(token: str) -> str:
    """Verify the token and return its subject claim."""
    from app.jwks import decode

    claims = decode(token)
    return claims["sub"]

